SELECT count(*) AS row_count, sum(a) AS sum_a, sum(length(b)) AS blob_bytes, min(a) AS min_a, max(a) AS max_a, sum(b=zeroblob(200)) AS exact_blobs, (SELECT count(*) FROM pragma_table_info('t1') WHERE pk>0) AS primary_key_columns, (SELECT wr FROM pragma_table_list WHERE schema='main' AND name='t1') AS without_rowid, (SELECT page_size FROM pragma_page_size) AS page_size, (SELECT auto_vacuum FROM pragma_auto_vacuum) AS auto_vacuum FROM t1;